<div id="cart-panel" class="hidden fixed inset-0 z-40 bg-black/30 p-3 sm:p-6"><section class="ml-auto flex h-full w-full max-w-md flex-col rounded-2xl bg-white p-6 shadow-2xl"><div class="flex items-center justify-between"><div><p class="text-xs font-bold uppercase tracking-widest text-brand-dark">Your order</p><h2 class="font-serif text-2xl font-bold">Cart</h2></div><button onclick="document.getElementById('cart-panel').classList.add('hidden')" class="h-10 w-10 rounded-xl bg-gray-100"><i class="fa-solid fa-xmark"></i></button></div><div id="cart-items" class="my-5 flex-1 space-y-3 overflow-y-auto"></div><div class="border-t border-gray-200 pt-4"><div class="mb-4 flex justify-between text-lg font-bold"><span>Total</span><span>₱<span id="cart-total">0.00</span></span></div><form id="checkout" class="space-y-3"><input required maxlength="100" name="customer_name" placeholder="Your name" class="w-full rounded-xl border border-gray-200 p-3 text-sm"><select id="order-type" name="order_type" class="w-full rounded-xl border border-gray-200 p-3 text-sm"><option value="dine_in">Dine in</option><option value="take_away">Take away</option></select><input id="table-number" name="table_number" min="1" type="number" value="<?= $tableNumber ?: '' ?>" placeholder="Table number" class="w-full rounded-xl border border-gray-200 p-3 text-sm"><p id="checkout-error" class="hidden text-sm text-red-600"></p><button class="w-full rounded-xl bg-brand py-3 font-bold text-brand-black">Send order <i class="fa-solid fa-arrow-right ml-1"></i></button></form></div></section></div><div id="success" class="hidden fixed inset-0 z-50 grid place-items-center bg-black/50 p-4"><div class="w-full max-w-sm rounded-3xl bg-white p-8 text-center shadow-2xl"><i class="fa-solid fa-circle-check text-4xl text-green-500"></i><h2 class="mt-3 font-serif text-2xl font-bold">Order received</h2><p class="mt-2 text-sm text-gray-600">Please show this reference to staff if needed.</p><p id="order-number" class="mt-4 rounded-xl bg-brand-light p-3 font-bold"></p><a href="./" class="mt-6 inline-block rounded-xl bg-brand-black px-5 py-3 font-bold text-brand">New order</a></div></div>
<script>const csrfToken=<?= json_encode(csrfToken()) ?>;let cart=JSON.parse(localStorage.getItem('yh_customer_cart')||'[]');function save(){localStorage.setItem('yh_customer_cart',JSON.stringify(cart));render()}function addItem(item){let x=cart.find(i=>i.id===item.id);x?x.quantity++:cart.push({...item,quantity:1});save()}function change(id,d){let x=cart.find(i=>i.id===id);if(!x)return;x.quantity+=d;if(x.quantity<1)cart=cart.filter(i=>i.id!==id);save()}function esc(s){let d=document.createElement('div');d.textContent=s;return d.innerHTML}function render(){document.getElementById('cart-count').textContent=cart.reduce((a,x)=>a+x.quantity,0);document.getElementById('cart-items').innerHTML=cart.length?cart.map(x=>`<div class="rounded-xl bg-gray-50 p-3"><div class="flex justify-between gap-2"><strong>${esc(x.name)}</strong><span>₱${(x.price*x.quantity).toFixed(2)}</span></div><div class="mt-2 flex items-center gap-3"><button onclick="change(${x.id},-1)" class="h-7 w-7 rounded-lg bg-white">−</button><span class="font-bold">${x.quantity}</span><button onclick="change(${x.id},1)" class="h-7 w-7 rounded-lg bg-white">+</button></div></div>`).join(''):'<p class="py-10 text-center text-sm text-gray-500">Your cart is empty.</p>';document.getElementById('cart-total').textContent=cart.reduce((a,x)=>a+x.price*x.quantity,0).toFixed(2)}document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.className='filter whitespace-nowrap rounded-xl border border-gray-200 bg-white px-4 py-2 text-sm font-bold text-gray-500');b.className='filter rounded-xl bg-brand-black px-4 py-2 text-sm font-bold text-brand';document.querySelectorAll('.menu-item').forEach(x=>x.hidden=b.dataset.category!='all'&&x.dataset.category!=b.dataset.category)});document.getElementById('order-type').onchange=e=>document.getElementById('table-number').classList.toggle('hidden',e.target.value!=='dine_in');document.getElementById('checkout').onsubmit=async e=>{e.preventDefault();let err=document.getElementById('checkout-error');err.classList.add('hidden');try{let r=await fetch('../customer-order.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),cart,csrf_token:csrfToken})}),o=await r.json();if(!o.success)throw Error(o.error);cart=[];save();document.getElementById('cart-panel').classList.add('hidden');document.getElementById('order-number').textContent=o.order_number;document.getElementById('success').classList.remove('hidden')}catch(x){err.textContent=x.message||'Could not place order.';err.classList.remove('hidden')}};const side=document.getElementById('sidebar');document.getElementById('sidebar-toggle').onclick=()=>{let open=side.classList.toggle('w-[240px]');side.classList.toggle('w-[80px]',!open);document.querySelectorAll('.nav-text,.brand-detail').forEach(x=>x.classList.toggle('hidden',!open));localStorage.setItem('yhCustomerSidebarOpen',open)};if(localStorage.getItem('yhCustomerSidebarOpen')==='true')document.getElementById('sidebar-toggle').click();else document.querySelectorAll('.nav-text,.brand-detail').forEach(x=>x.classList.add('hidden'));render();</script></body></html>
